// Honey — the picture that tastes of one ingredient.
// A macro photograph of thick golden honey ribboning off a wooden dipper
// onto honeycomb, warm amber light on a dark brown ground. The picture is
// embedded below as a single base64 JPEG; this script decodes it, checks
// it against the entry limits, and writes it to /output/entry.png.
import { mkdirSync, writeFileSync } from "node:fs";

const IMAGE_BASE64 = "";

const MAX_BYTES = 1_048_576;
const MAX_DIM = 1024;

type Dimensions = { width: number; height: number };

// Walk the JPEG marker segments until a Start-of-Frame segment appears,
// then read the picture's height and width from it. Written from the JPEG
// layout itself: each segment opens with 0xFF, carries a two-byte length
// that counts its own two bytes, and an SOF segment stores the height
// followed by the width just after that length.
function jpegDimensions(buf: Buffer): Dimensions {
  if (buf[0] !== 0xff || buf[1] !== 0xd8) {
    throw new Error("not a JPEG: missing SOI marker");
  }
  let offset = 2;
  while (offset + 1 < buf.length) {
    if (buf[offset] !== 0xff) {
      throw new Error(`bad marker at offset ${offset}`);
    }
    const marker = buf[offset + 1];
    if (marker === 0xff) {
      // A 0xFF fill byte, not a marker — step past it.
      offset += 1;
      continue;
    }
    if (marker === 0xd9) {
      throw new Error("reached EOI without finding an SOF marker");
    }
    if (marker === 0x01 || (marker >= 0xd0 && marker <= 0xd7)) {
      // TEM and the RSTn markers carry no length field.
      offset += 2;
      continue;
    }
    const segmentLength = buf.readUInt16BE(offset + 2);
    if (segmentLength < 2 || offset + 2 + segmentLength > buf.length) {
      throw new Error("marker segment overruns buffer");
    }
    // SOF0–SOF15, leaving out DHT (0xC4), JPG (0xC8) and DAC (0xCC):
    // they share the 0xC0–0xCF range but are not frame headers.
    const isFrameHeader =
      marker >= 0xc0 &&
      marker <= 0xcf &&
      marker !== 0xc4 &&
      marker !== 0xc8 &&
      marker !== 0xcc;
    if (isFrameHeader) {
      const height = buf.readUInt16BE(offset + 5);
      const width = buf.readUInt16BE(offset + 7);
      return { width, height };
    }
    offset += 2 + segmentLength;
  }
  throw new Error("no SOF marker found");
}

function main(): void {
  const bytes = Buffer.from(IMAGE_BASE64, "base64");
  if (bytes.length === 0) {
    throw new Error("image is empty: nothing decoded from the embedded JPEG");
  }
  if (bytes.length > MAX_BYTES) {
    throw new Error(`image size ${bytes.length} bytes exceeds ${MAX_BYTES}`);
  }
  const { width, height } = jpegDimensions(bytes);
  if (width > MAX_DIM || height > MAX_DIM) {
    throw new Error(`image ${width}x${height} exceeds ${MAX_DIM}x${MAX_DIM}`);
  }
  mkdirSync("/output", { recursive: true });
  writeFileSync("/output/entry.png", bytes);
  console.log(`wrote /output/entry.png: ${width}x${height} JPEG, ${bytes.length} bytes`);
}

main();
